/**
 * AI SDK adapter. One implementation serves every provider: the
 * caller-supplied AI SDK model instance (`gateway('openai/gpt-6-luna-fast')`,
 * `openrouter(...)`, `openai('gpt-6-luna-fast')`, a local provider, a scripted test
 * model) is used as is. Everything after the model — bounded requests,
 * closed-grammar validation, usage and error translation — is
 * provider-independent.
 */
import { type ResolvedModel } from '../../config/agent.ts';
import { type SdkLanguageModel } from '../ai-sdk.ts';
import { AgentError } from '../error.ts';
import { type ModelAdapter } from './adapter.ts';
/**
 * Provider transport retries; distinct from runner-owned model-call budget.
 *
 * Rate limits and 5xx bursts are the dominant cause of spurious agent-step
 * failures, and the SDK only retries errors the provider marked retryable,
 * honoring `retry-after` before its own exponential backoff. Raising the SDK
 * default of 2 costs nothing on a healthy provider: `timeout` below is merged
 * into the signal the retry loop waits on, so the step deadline — not the
 * attempt count — bounds the whole chain. The act loop sends the same count
 * and the same kind of timeout, so both tiers fail a flaky provider alike.
 */
export declare const TRANSPORT_RETRIES = 5;
/**
 * Creates the adapter for one resolved model, or fails with
 * MODEL_UNAVAILABLE naming `agentName`, the agents entry that holds none.
 */
export declare function createModelAdapter(model: ResolvedModel | undefined, agentName?: string): ModelAdapter;
/**
 * The bare AI SDK language model of one resolved model, for callers that
 * drive the SDK directly (the default step executor) rather than through the
 * adapter.
 */
export declare function instantiateLanguageModel(model: ResolvedModel): SdkLanguageModel;
/** The AI SDK usage fields the runner reads, structurally. */
export interface SdkUsage {
    readonly inputTokens?: number | undefined;
    readonly outputTokens?: number | undefined;
    readonly inputTokenDetails?: {
        readonly cacheReadTokens?: number | undefined;
        readonly cacheWriteTokens?: number | undefined;
    } | undefined;
}
/**
 * The prompt-cache split of one call's input, when the provider reported it.
 * Providers that cache nothing report zeros; providers that do not report the
 * split leave the fields undefined, and so does the report.
 */
export declare function cacheTokenFields(usage: SdkUsage | undefined): {
    cacheReadTokens?: number;
    cacheWriteTokens?: number;
};
/**
 * Per-request cost, where the provider reports one in its metadata. The
 * Vercel AI Gateway's `cost` is what it bills; BYOK routes bill the provider
 * key directly and report `cost: "0"`, so fall back to `marketCost`, the
 * list-price estimate of the same request. OpenRouter reports `usage.cost`
 * when its provider is asked to account usage. Other providers simply lack
 * the key.
 */
export declare function readCost(metadata: Readonly<Record<string, Readonly<Record<string, unknown>>>> | undefined): number | undefined;
/** Whether an AI SDK `NoObjectGeneratedError` or `ToolChoiceViolationError` says the model refused the call. */
export declare function isModelRefusal(error: unknown): boolean;
/** `MODEL_REFUSED` naming the model and the provider's raw finish reason when it sent one. */
export declare function modelRefusalError(model: Pick<ResolvedModel, 'provider' | 'id'>, rawFinishReason: string | undefined, cause?: unknown): AgentError;
/** A marked failure (`internal/unserved-model.ts`) as the run-stopping `MODEL_UNAVAILABLE` the fixture reports once, or that error itself; undefined for any other failure. */
export declare function unservedModelError(cause: unknown): AgentError | undefined;
/** True for an error `unservedModelError` built, in this realm or another. */
export declare function isUnservedModelError(value: unknown): value is AgentError;
/**
 * The remedy a provider failure points at, when its shape names one: a
 * rejected credential, or a conversation the provider kept no state for.
 * Requires the SDK to be loaded, which every caller has done by the time a
 * provider call has failed.
 */
export declare function failureHint(cause: unknown): string;
/**
 * True when a provider call ended by abort or timeout rather than by a
 * provider answer, including a retry chain the deadline cut short. Requires
 * the SDK to be loaded, which every caller has done by the time a call failed.
 */
export declare function isAbort(cause: unknown): boolean;
